package com.hydra.firewall

import android.content.Context
import com.hydra.firewall.ui.theme.HydraCard
import java.util.Locale
import androidx.compose.foundation.layout.*
import androidx.compose.foundation.rememberScrollState
import androidx.compose.foundation.verticalScroll
import androidx.compose.material3.*
import androidx.compose.runtime.Composable
import androidx.compose.ui.Modifier
import androidx.compose.ui.text.font.FontWeight
import androidx.compose.ui.unit.dp

@Composable
fun HelpScreen(context: Context, language: AppLanguage) {
    val en = language.isEnglish() || (language == AppLanguage.SYSTEM && Locale.getDefault().language.equals("en", true))
    val title = if (en) "How to use Hydra Firewall" else "Cómo usar Hydra Firewall"
    val intro = if (en) {
        "Hydra Firewall is a no-root Android firewall. It uses Android's local VPN/TUN interface to inspect and filter application traffic. You do not need root access."
    } else {
        "Hydra Firewall es un firewall Android sin root. Utiliza la interfaz VPN/TUN local de Android para inspeccionar y filtrar el tráfico de las aplicaciones. No necesitás acceso root."
    }

    data class HelpSection(val title: String, val body: String)
    val sections = if (en) listOf(
        HelpSection("Navigation (2.0)", "The bottom bar has 5 destinations. Home: the firewall switch and core protection. Apps: Rules, plus IP/Ports (with Cleanup) and Profiles in Advanced mode. Activity: Connections and Statistics, plus the Analyzer in Advanced mode. Security: in Normal mode a single screen (status, suspicious apps, quarantine, update watch, security history); in Advanced mode a row of sections adds Tools (APK scanner (experimental), traffic correlation and Doze). Home in Normal mode shows only the switch, pause, Security status, the 7-day summary and Threats + ads; Settings has 5 blocks (Protection, Notifications, Appearance, Data and backups, Advanced); Apps filters are All / No Internet / New (the full filter row is in Advanced); notices that need your decision always ring, informational ones are silent and can be turned off in Settings → Notifications. More: Settings, Help, About and Test (Advanced). Where a destination has several screens, a row of buttons at the top switches between them."),
        HelpSection("Sensitive permissions and ignored apps (2.2)", "Security also shows apps installed outside a known store that combine sensitive permissions (for example accessibility + overlay + SMS). These are indications, not proof: each one is explained in plain words, and you can search Google or tap Ignore. Ignored apps (threats and permissions) are listed with the date; if an ignored app changes its developer signature, Hydra watches it again and notifies you. Pattern-only matches on apps from a known store or on system apps are not reported (they are mostly false positives); an exact known-malware hash always is. In Advanced mode, Copy results in the MH-100K scanner (experimental: the score is a guide, not a verdict) adds version, date and each app's source (store/sideload/system); tools/analyze_scan_results.py turns that into a score distribution and a suggested threshold."),
        HelpSection("1b. Pause, tile and summary", "On Home, \"Pause 15 min / 1 h\" turns Hydra off temporarily and back on by itself (countdown and Resume now). If Android blocks the automatic restart you get a notification: tap it. The Quick Settings tile does the same from the Android panel (add it by editing the panel). Home also shows the last 7 days: blocked attempts, ads/trackers blocked and the apps with most blocks (local counters only). In a blocked connection's details, \"Allow this app\" fixes an app that stopped working, and \"Allow for 1 hour\" lets it connect for a while and puts the rule back by itself. Settings → Data and backups → \"Copy diagnostic report\" copies versions, switches and security event titles (no destinations) to paste into a bug report."),
        HelpSection("1. Start / stop the firewall", "Use the Firewall VPN switch in the PROTECTION tab. The first time Android asks for VPN permission, accept it. When Hydra is ON, allowed application traffic is processed by Hydra before being forwarded to the network."),
        HelpSection("Normal and Advanced mode", "Normal mode (the default) keeps things simple: Security is one screen, the first-connection prompt only asks Allow or Block (More options shows the rest) and Settings shows only the basics (ask on first connection, language, appearance, app lock, maintenance, updates). Advanced mode adds IP/Ports, Profiles, Analyzer and Test, the extra Security sections and the technical settings (global mode, default Wi-Fi/mobile, secure DNS, IPv6, roaming, screen-off, performance, permissive apps). The switch is in Settings, and Security has a button to turn it on. Switching mode never deletes rules. A short guide appears the first time Hydra opens."),
        HelpSection("First-connection prompt", "When an app with no rule connects for the first time, Hydra asks. Wi-Fi and Mobile start ON. ALLOW keeps the rule; PERMISSIVE also relaxes compatibility layers (domain/QUIC filtering) while strong threat/IP protection stays on, and it does NOT exempt the app from Block All; PERSONALIZED lets you pick protections for that app only; NO FIREWALL lets the app use Android's normal network outside Hydra; BLOCK denies it. Details explains why the app is connecting. In Normal mode you only see ALLOW and BLOCK; tap More options for PERMISSIVE, NO FIREWALL, PERSONALIZED, the Wi-Fi/Mobile switches and Details."),
        HelpSection("Usage and threat-pack cards", "Statistics ranks apps by daily consumption. Security shows the status of the signed threat pack (age, indicators, source) with an Update now button; automatic updates need your own signing key and feed, see docs/THREAT-PACK.md."),
        HelpSection("Antivirus and Control panel (Security → Overview)", "The Control and updates card gathers, in one place, the switch or Update button for each layer: Firewall (VPN), threat pack, antivirus and domain blocklists. The antivirus checks your installed apps against the signed threat pack (known-malware SHA-256 hashes and YARA-Lite patterns) when an app is installed or updated, and again when the pack updates. Installs/updates are caught instantly only while the firewall (VPN) is ON; otherwise new or changed apps are checked when you open Hydra and on the daily pack update. It only finds KNOWN threats: it is not a full antivirus and does not replace Google Play Protect. A hash match means a known malicious file; a pattern-only match may be a false positive. Hydra never uninstalls anything by itself: you decide. You can turn the automatic check off or run it on demand. Right after installing or updating, Hydra downloads the pack and checks all your apps by itself; while that runs the status card shows “Getting protection ready…” with progress and the Check buttons stay disabled until “You are protected” appears."),
        HelpSection("Updating Hydra and suspicious apps", "Security → Overview → Hydra update checks GitHub Releases once a day (and when you tap Check for update) and tells you when you are already up to date. It downloads only on unmetered networks, verifies the SHA-256 and that it is signed with the same key as the installed app, and Android always asks you to confirm. For an app flagged by the antivirus, Copy details copies everything useful (package, version, installer, hashes, permissions, matching rules) and the small Google button searches the web so you can judge whether it is really suspicious. If you decide it is not a problem, Ignore moves it to the Ignored apps list (it is not reported again unless it later matches different rules) and Watch again brings it back."),
        HelpSection("2. Rules", "This is the main control panel. Each application can have its own Wi-Fi and mobile-data decision. ALLOW lets the traffic through; BLOCK prevents it. When you allow an app that has no rule yet (from this tab or from the first-connection prompt), both Wi-Fi and mobile data start ON; turn off the one you do not want. The ▼ badge at the bottom of the list means there are more apps below. You can also use first-connection prompts and schedules."),
        HelpSection("3. IPs and ports (Advanced mode)", "This tab only shows in Advanced mode; rules you created stay active even when it is hidden. Use IP blocking when you want to stop traffic to a specific destination. Advanced port rules let you control TCP/UDP traffic by protocol and port. These rules complement per-app rules."),
        HelpSection("4. Connections", "Shows the connection history recorded by Hydra: application, destination, protocol, port, decision and time. Use it to understand what an application is contacting and why a connection was allowed or blocked."),
        HelpSection("5. Analyzer (Advanced mode)", "The analyzer summarizes live traffic by application, DNS, blocked connections and destinations. It is for visibility and investigation; enabling Learning Analysis does not change firewall decisions."),
        HelpSection("6. Statistics", "Shows traffic totals and activity over time. Allowed and blocked traffic are counted separately so you can see how much traffic Hydra has processed."),
        HelpSection("7. Profiles (Advanced mode)", "Profiles also hold export/import of your whole configuration (rules, schedules, permissive apps) as a file; export before reinstalling. Profiles let you save and reuse groups of firewall settings. They are useful for different situations such as normal use, stricter filtering or a temporary configuration."),
        HelpSection("8. Security", "Security has its own destination in the bottom bar, so every control lives in one place and nothing is repeated. Security shows the protection status, apps worth reviewing (known threats and sensitive-permission indications, each with a plain-language reason), quarantine, update watch and the security history. If the VPN stopped by itself, a card says so. Some detections are indicators and should not be interpreted as proof of malware by themselves."),
        HelpSection("9. Settings", "Settings control the firewall policy and behavior. Blacklist mode normally allows traffic unless a rule blocks it; whitelist mode is stricter and uses explicit permissions. Other options include unknown UID handling, local-network access, roaming, screen-off blocking, Secure DNS, ad/tracker blocking, language, appearance and battery options."),
        HelpSection("10. Block All", "BLOCK ALL is the emergency/global block switch. It blocks all traffic that goes through Hydra\'s tunnel, with no per-app rules. Exceptions: Hydra itself and apps set to NO FIREWALL / excluded (compatibility mode) are outside the tunnel and are NOT blocked. Not a full kill switch: for total cutoff use Android\'s Always-on VPN + \"Block connections without VPN\"."),
        HelpSection("11. Secure DNS", "Secure DNS can intercept IPv4 DNS traffic on UDP/53 and forward DNS through encrypted DNS-over-TLS. This protects the DNS transport, but DNS-over-HTTPS inside an application's HTTPS connection can prevent Hydra from seeing the queried domain itself."),
        HelpSection("12. Always-on and Lockdown", "Android can keep a supported VPN as Always-on. Lockdown is an Android system mode that prevents apps from bypassing the VPN while the VPN is configured that way. It is stronger but can also leave apps without networking if the VPN is unavailable, so use it intentionally."),
        HelpSection("13. IPv6", "Settings has a Block IPv6 switch: it drops all IPv6 traffic immediately and apps fall back to IPv4, where every filter applies. Without it, Hydra routes IPv6 global and ULA traffic through the firewall. IPv6 link-local and multicast traffic are intentionally treated as local Android networking and are not routed through Hydra. This preserves compatibility with local discovery and networking features."),
        HelpSection("14. What Hydra can and cannot see", "Hydra can filter network traffic by application, IP, protocol, port and other available metadata. Encryption such as HTTPS, DoH or application-level encryption can hide the content and some domain information. Hydra should therefore be understood as a network firewall, not as a universal decryption engine."),
        HelpSection("15. If an app does not work", "First check Connections and Analyzer to see what Hydra blocked. Then inspect that application's rule, Wi-Fi/mobile switches, IP blocks, schedules and global settings. If necessary, temporarily allow the application to identify which rule is responsible."),
        HelpSection("16. Important note", "Hydra is designed to filter normal IP traffic routed through its VPN interface. Android system/local traffic has special networking behavior, and Hydra does not claim to control every local or multicast packet. Always-on/Lockdown and the VPN itself are controlled by Android's VPN framework."),
        HelpSection("17. HYDRA SECURITY ENGINE", "The Security Engine adds a security-analysis layer over the existing firewall. It combines APK inspection, application-risk indicators, traffic correlation, quarantine and security events. It is designed to provide evidence and leads for investigation without replacing the firewall's network policy."),
        HelpSection("18. APK Scanner", "APK Scanner can inspect an APK file or an installed application. It calculates SHA-256, reads the package/version and signing-certificate fingerprints, lists requested permissions and counts activities, services, receivers and providers. It also checks exported components, Accessibility services, Device Admin receivers, overlay capability, package-install capability, debuggable status, native .so libraries and DEX files."),
        HelpSection("19. APP RISK", "APP RISK combines several indicators into a 0–100 score with the levels SAFE, LOW, MEDIUM, HIGH and CRITICAL. High-impact combinations such as Accessibility plus overlay/package-install capability receive more weight. A risk score is an analysis signal, not a malware verdict: permissions, exported components or native code can also be legitimate in normal applications."),
        HelpSection("20. BEHAVIOR ENGINE", "The Behavior Engine correlates metadata that Hydra already collects: connections, destinations, DNS activity, DNS blocks, and unusual ports. It produces an application behavior score and risk level for review. It does not inspect encrypted payloads and does not change firewall decisions by itself."),
        HelpSection("21. THREAT INTELLIGENCE", "Hydra Security Engine is local-first. Known-bad indicators are used locally. The current engine does not automatically upload APKs or traffic data to external reputation services. Future online reputation sources can be added separately without making them a requirement for the local security analysis."),
        HelpSection("22. Rule cleanup and unexpected stops", "Apps → IP and ports → Cleanup (Advanced mode) lists IP blocks and port rules that duplicate each other or are already covered by a broader rule, and removes the redundant entry on request. When the VPN service stops without you asking, Hydra shows a notification and a card in Security, and restarts the service by itself."),
        HelpSection("23. Quarantine", "When new-app quarantine is enabled, newly installed applications can be placed in a network quarantine so they are reviewed before normal access. Quarantine is a network-control mechanism; it does not silently uninstall or modify the APK. Existing applications are not retroactively quarantined when the feature is enabled."),
        HelpSection("24. Security events and status", "Security events record important findings such as APK scans and security indicators so they can be correlated with the current state. Security → Security history lists them with their dates (antivirus matches, ignored apps, signature changes, quarantine). In Advanced mode the status list also summarizes quarantine, service state and update/Doze monitoring. These indicators help investigation; they should always be interpreted together with the application's context."),
        HelpSection("25. Security Engine limitations", "The Security Engine is not a universal malware detector or antivirus. It does not claim to decrypt HTTPS, inspect application payloads or prove malicious intent from a single indicator. Use the score, indicators, network behavior and TLS information as evidence for review, and confirm important findings with additional analysis when necessary."),
        HelpSection("26. \"Threat intelligence (0 domains)\" in Security", "This row is separate from the ad/tracker blocklist, which is bundled in the app and already active. It counts a dedicated malware/threat domain list (currently HaGeZi Threat Intelligence mini) that only gets populated when you run an update from the blocklist update screen with that source enabled. Until you do that at least once, this row normally stays at 0 domains — that is expected on a fresh install, not an error."),
        HelpSection("27. \"Local behavior learning (0 apps)\" in Security", "This counts how many apps already have an on-device traffic baseline. It depends on the Analyzer's traffic recording, which is OFF by default. Turn on recording in the Analyzer tab, use the phone normally for a while so real traffic gets logged, then reopen Security Center — that screen recalculates this number from the recorded traffic each time you open it. With recording off, this stays at 0 even though the firewall itself is filtering traffic normally."),
    ) else listOf(
        HelpSection("Navegación (2.0)", "La barra inferior tiene 5 destinos. Inicio: el interruptor del firewall y la protección básica. Apps: Reglas, más IP/Puertos (con Limpieza) y Perfiles en modo Avanzado. Actividad: Conexiones y Estadísticas, más el Analizador en modo Avanzado. Seguridad: en modo Normal una sola pantalla (estado, apps sospechosas, cuarentena, vigilancia de updates, historial de seguridad); en modo Avanzado una fila de secciones suma Herramientas (analizador APK (experimental), correlación de tráfico y Doze). Inicio en modo Normal muestra solo el interruptor, la pausa, el estado de Seguridad, el resumen de 7 días y Amenazas + publicidad; Ajustes tiene 5 bloques (Protección, Notificaciones, Apariencia, Copias y datos, Avanzado); los filtros de Apps son Todas / Sin Internet / Nuevas (la fila completa está en Avanzado); los avisos que necesitan tu decisión siempre suenan, los informativos son silenciosos y se apagan en Ajustes → Notificaciones. Más: Ajustes, Ayuda, Acerca de y Prueba (Avanzado). Donde un destino tiene varias pantallas, una fila de botones arriba permite cambiar entre ellas."),
        HelpSection("1b. Pausa, atajo y resumen", "En Inicio, «Pausar 15 min / 1 h» apaga Hydra un rato y lo vuelve a encender solo (cuenta regresiva y Reanudar ahora). Si Android no deja reiniciarlo solo, te llega una notificación: tocala. El atajo del panel de Android (agregalo editando el panel) hace lo mismo. Inicio también muestra los últimos 7 días: intentos bloqueados, anuncios/rastreadores bloqueados y las apps con más bloqueos (solo contadores locales). En el detalle de una conexión bloqueada, «Permitir esta app» arregla una app que dejó de funcionar y «Permitir por 1 hora» la deja conectarse un rato y vuelve a poner la regla sola. Ajustes → Copias y datos → «Copiar diagnóstico» copia versiones, interruptores y títulos de eventos de seguridad (sin destinos) para pegar en un reporte de problema."),
        HelpSection("1. Encender / apagar el firewall", "Usá el interruptor VPN del firewall en la pestaña PROTECCIÓN. La primera vez Android va a pedir permiso para crear la VPN; aceptalo. Cuando Hydra está encendido, el tráfico permitido de las aplicaciones es procesado por Hydra antes de salir a la red."),
        HelpSection("Modo normal y avanzado", "El modo Normal (por defecto) es simple: Seguridad es una sola pantalla, el aviso de primera conexión solo pregunta Permitir o Bloquear (Más opciones muestra el resto) y Ajustes muestra solo lo básico (preguntar en la primera conexión, idioma, apariencia, bloqueo de la app, mantenimiento, actualizaciones). El modo Avanzado agrega IP/Puertos, Perfiles, Analizador y Prueba, las secciones extra de Seguridad y los ajustes técnicos (modo global, Wi‑Fi/móvil por defecto, DNS seguro, IPv6, roaming, pantalla apagada, rendimiento, apps permisivas). El interruptor está en Ajustes, y Seguridad tiene un botón para activarlo. Cambiar de modo nunca borra reglas. La primera vez que se abre Hydra aparece una guía corta."),
        HelpSection("Aviso de primera conexión", "Cuando una app sin regla se conecta por primera vez, Hydra pregunta. Wi‑Fi y Móvil arrancan ACTIVADOS. PERMITIR guarda la regla; PERMISIVO además relaja las capas de compatibilidad (filtrado de dominios/QUIC) manteniendo la protección fuerte contra amenazas/IP, y NO exceptúa a la app de Bloquear todo; PERSONALIZADO elige protecciones solo para esa app; SIN FIREWALL deja que la app use la red normal de Android fuera de Hydra; BLOQUEAR la deniega. Detalles explica por qué se conecta la app. En modo Normal solo ves PERMITIR y BLOQUEAR; tocá Más opciones para PERMISIVO, SIN FIREWALL, PERSONALIZADO, los interruptores Wi‑Fi/Móvil y Detalles."),
        HelpSection("Consumo y paquete de amenazas", "Estadísticas ordena las apps por consumo diario. Seguridad muestra el estado del paquete de amenazas firmado (antigüedad, indicadores, origen) con el botón Actualizar ahora; las actualizaciones automáticas requieren tu propia clave de firma y feed, ver docs/THREAT-PACK.md."),
        HelpSection("Antivirus y Panel de control (Seguridad → Resumen)", "La tarjeta Control y actualizaciones reúne en un solo lugar el interruptor o el botón Actualizar de cada capa: Firewall (VPN), pack de amenazas, antivirus y listas de dominios. El antivirus revisa tus apps instaladas contra el pack de amenazas firmado (hashes SHA‑256 de malware conocido y patrones YARA‑Lite) cuando una app se instala o se actualiza, y otra vez cuando el pack se actualiza. Las instalaciones/actualizaciones se detectan al instante solo con el firewall (VPN) ACTIVO; si no, las apps nuevas o modificadas se revisan al abrir Hydra y en la actualización diaria del pack. Solo detecta amenazas CONOCIDAS: no es un antivirus completo ni reemplaza a Google Play Protect. Una coincidencia de hash indica un archivo malicioso conocido; una coincidencia solo de patrón puede ser un falso positivo. Hydra nunca desinstala nada por sí sola: decidís vos. Podés apagar la revisión automática o ejecutarla a pedido. Justo después de instalar o actualizar, Hydra descarga el pack y revisa todas tus apps sola; mientras tanto la tarjeta de estado muestra «Preparando la protección…» con el avance y los botones Revisar quedan deshabilitados hasta que aparece «Estás protegido»."),
        HelpSection("Permisos delicados y apps ignoradas (2.2)", "Seguridad también muestra apps instaladas fuera de una tienda conocida que combinan permisos delicados (por ejemplo accesibilidad + superposición + SMS). Son indicios, no pruebas: cada uno se explica en palabras simples y podés buscar en Google o tocar Ignorar. Las apps ignoradas (amenazas y permisos) aparecen con la fecha; si una app ignorada cambia su firma de desarrollador, Hydra la vuelve a vigilar y te avisa. Las coincidencias solo de patrón en apps de una tienda conocida o del sistema no se informan (casi siempre son falsos positivos); un hash exacto de malware conocido siempre se informa. En modo Avanzado, Copiar resultados en el escáner MH-100K (experimental: el puntaje es orientativo, no un veredicto) agrega versión, fecha y el origen de cada app (store/sideload/system); tools/analyze_scan_results.py lo convierte en una distribución de puntajes y un umbral sugerido."),
        HelpSection("Actualizar Hydra y apps sospechosas", "Seguridad → Resumen → Actualización de Hydra consulta los Releases de GitHub una vez al día (y cuando tocás Buscar actualización) y te avisa cuando ya estás al día. Solo descarga en redes sin datos medidos, verifica el SHA‑256 y que esté firmada con la misma clave que la app instalada, y Android siempre te pide confirmar. Si el antivirus marca una app, Copiar datos copia todo lo útil (paquete, versión, instalador, hashes, permisos, reglas coincidentes) y el botón chico Google busca en la web para que puedas juzgar si es realmente sospechosa. Si decidís que no es un problema, Ignorar la pasa a la lista Apps ignoradas (no se vuelve a avisar salvo que luego coincida con otras reglas) y Volver a vigilar la trae de vuelta."),
        HelpSection("2. Reglas", "Es el panel principal. Cada aplicación puede tener una decisión independiente para Wi-Fi y datos móviles. PERMITIR deja pasar el tráfico; BLOQUEAR lo impide. Al permitir una app que todavía no tiene regla (desde esta pestaña o desde el aviso de primera conexión), Wi‑Fi y datos móviles arrancan ACTIVADOS; apagá el que no quieras. El cartel ▼ al pie de la lista indica que hay más apps abajo. También podés usar preguntas en la primera conexión y horarios."),
        HelpSection("3. IP y puertos (modo avanzado)", "Esta pestaña solo aparece en modo avanzado; las reglas ya creadas siguen activas aunque esté oculta. Usá el bloqueo de IP para impedir tráfico hacia un destino concreto. Las reglas avanzadas permiten controlar TCP/UDP por protocolo y puerto. Complementan las reglas por aplicación."),
        HelpSection("4. Conexiones", "Muestra el historial de conexiones registrado por Hydra: aplicación, destino, protocolo, puerto, decisión y hora. Sirve para saber qué está intentando contactar una aplicación y por qué una conexión fue permitida o bloqueada."),
        HelpSection("5. Analizador (modo avanzado)", "Resume el tráfico en vivo por aplicación, DNS, conexiones bloqueadas y destinos. Sirve para observar e investigar; activar el Análisis de aprendizaje no modifica las decisiones del firewall."),
        HelpSection("6. Estadísticas", "Muestra totales de tráfico y actividad a lo largo del tiempo. El tráfico permitido y bloqueado se contabiliza por separado."),
        HelpSection("7. Perfiles (modo avanzado)", "También permite exportar/importar toda tu configuración (reglas, horarios, apps permisivas) como archivo; exportá antes de reinstalar. Permiten guardar y reutilizar grupos de configuraciones del firewall. Son útiles para distintas situaciones, como uso normal, filtrado más estricto o una configuración temporal."),
        HelpSection("8. Seguridad", "Seguridad tiene su propio destino en la barra inferior, así todo está en un solo lugar y nada se repite. Seguridad muestra el estado de la protección, las apps que conviene revisar (amenazas conocidas e indicios de permisos delicados, cada uno con su motivo en lenguaje simple), la cuarentena, la vigilancia de updates y el historial de seguridad. Si la VPN se detuvo sola, una tarjeta lo avisa. Algunas detecciones son indicadores y no deben interpretarse por sí solas como prueba de malware."),
        HelpSection("9. Ajustes", "Controlan la política y el comportamiento del firewall. Lista negra normalmente permite el tráfico salvo que exista una regla que lo bloquee; lista blanca es más estricta y usa permisos explícitos. También están UID desconocido, red local, roaming, bloqueo con pantalla apagada, DNS seguro, bloqueo de anuncios/rastreadores, idioma, apariencia y opciones de batería."),
        HelpSection("10. BLOQUEAR TODO", "BLOQUEAR TODO es el bloqueo global/de emergencia. Bloquea todo el tráfico que pasa por el túnel de Hydra, sin reglas por app. Excepciones: Hydra misma y las apps en SIN FIREWALL / excluidas (modo compatibilidad) quedan fuera del túnel y NO se bloquean. No es un corte total: para eso usa VPN siempre activa + «Bloquear conexiones sin VPN» de Android."),
        HelpSection("11. DNS seguro", "DNS seguro puede interceptar el DNS IPv4 por UDP/53 y enviarlo mediante DNS-over-TLS cifrado. Protege el transporte DNS, pero una aplicación que use DNS-over-HTTPS dentro de HTTPS puede impedir que Hydra vea directamente el dominio consultado."),
        HelpSection("12. Always-on y Lockdown", "Android puede mantener una VPN compatible como Always-on. Lockdown es un modo del sistema Android que impide que las aplicaciones salteen la VPN cuando está configurado de esa forma. Es más estricto, pero si la VPN no está disponible también puede dejar a las aplicaciones sin red; usalo conscientemente."),
        HelpSection("13. IPv6", "En Ajustes hay un interruptor Bloquear IPv6: descarta todo el tráfico IPv6 al instante y las apps pasan a IPv4, donde aplican todos los filtros. Sin él, Hydra enruta por el firewall el tráfico IPv6 global y ULA. El tráfico IPv6 link-local y multicast se trata intencionalmente como red local de Android y no se enruta por Hydra. Esto preserva la compatibilidad con funciones de descubrimiento y conectividad local."),
        HelpSection("14. Qué puede y qué no puede ver Hydra", "Hydra puede filtrar tráfico por aplicación, IP, protocolo, puerto y otros metadatos disponibles. HTTPS, DoH y otras formas de cifrado pueden ocultar el contenido y parte de la información de dominio. Hydra debe entenderse como firewall de red, no como un sistema universal de descifrado."),
        HelpSection("15. Si una aplicación deja de funcionar", "Primero mirá Conexiones y Analizador para ver qué bloqueó Hydra. Después revisá la regla de la aplicación, los interruptores de Wi‑Fi/datos, IP bloqueadas, horarios y ajustes globales. Si hace falta, permití temporalmente la aplicación para identificar qué regla estaba causando el bloqueo."),
        HelpSection("16. Importante", "Hydra está diseñado para filtrar el tráfico IP normal que el sistema enruta hacia su interfaz VPN. Android tiene comportamientos especiales para tráfico local y multicast, y Hydra no afirma controlar cada paquete local o multicast. Always-on, Lockdown y la propia VPN son mecanismos gestionados por el framework VPN de Android."),
        HelpSection("17. HYDRA SECURITY ENGINE", "El Security Engine agrega una capa de análisis de seguridad sobre el firewall existente. Combina inspección de APK, indicadores de riesgo de aplicaciones, correlación de tráfico, cuarentena y eventos de seguridad. Su objetivo es aportar evidencias y señales para investigar sin reemplazar la política de red del firewall."),
        HelpSection("18. APK Scanner", "El APK Scanner puede analizar un archivo APK o una aplicación instalada. Calcula SHA-256, muestra paquete/versión y huellas de los certificados de firma, lista permisos solicitados y cuenta activities, services, receivers y providers. También revisa componentes exportados, servicios de Accessibility, receivers de Device Admin, capacidad de overlay, instalación de paquetes, modo debuggable, librerías nativas .so y archivos DEX."),
        HelpSection("19. APP RISK", "APP RISK combina varios indicadores en un puntaje de 0–100 con niveles SAFE, LOW, MEDIUM, HIGH y CRITICAL. Las combinaciones de alto impacto, como Accessibility junto con overlay o instalación de paquetes, reciben mayor peso. El puntaje es una señal de análisis, no un veredicto de malware: permisos, componentes exportados o código nativo también pueden ser totalmente legítimos."),
        HelpSection("20. BEHAVIOR ENGINE", "El Behavior Engine correlaciona metadatos que Hydra ya recopila: conexiones, destinos, actividad DNS, bloqueos DNS, y puertos inusuales. Genera un puntaje y nivel de riesgo de comportamiento por aplicación para revisar. No inspecciona el contenido cifrado ni cambia por sí mismo las decisiones del firewall."),
        HelpSection("21. THREAT INTELLIGENCE", "El Security Engine funciona con un enfoque local-first. Los indicadores conocidos se utilizan localmente. El motor actual no sube automáticamente APK ni datos de tráfico a servicios externos de reputación. En el futuro se pueden agregar fuentes online de reputación por separado, sin hacerlas obligatorias para el análisis local."),
        HelpSection("22. Limpieza de reglas y paradas inesperadas", "Apps → IP y puertos → Limpieza (modo Avanzado) lista los bloqueos de IP y reglas de puerto que se repiten o que ya cubre una regla más amplia, y elimina la entrada redundante si lo pedís. Cuando el servicio VPN se detiene sin que lo pidas, Hydra muestra una notificación y una tarjeta en Seguridad, y reinicia el servicio sola."),
        HelpSection("23. Cuarentena", "Cuando la cuarentena de apps nuevas está habilitada, las aplicaciones recién instaladas pueden quedar en cuarentena de red para ser revisadas antes de tener acceso normal. La cuarentena es un mecanismo de control de red; no desinstala ni modifica silenciosamente el APK. Las aplicaciones existentes no se ponen en cuarentena retroactivamente al activar la función."),
        HelpSection("24. Eventos y estado de seguridad", "Los eventos de seguridad registran hallazgos importantes, como análisis de APK e indicadores de seguridad, para poder correlacionarlos con el estado actual. Seguridad → Historial de seguridad los lista con su fecha (coincidencias del antivirus, apps ignoradas, cambios de firma, cuarentena). En modo Avanzado, el estado también resume cuarentena, estado del servicio y vigilancia de actualizaciones/Doze. Estos indicadores ayudan a investigar y deben interpretarse junto con el contexto de cada aplicación."),
        HelpSection("25. Limitaciones del Security Engine", "El Security Engine no es un detector universal de malware ni un antivirus. No pretende descifrar HTTPS, inspeccionar el contenido de las aplicaciones ni demostrar intención maliciosa a partir de un único indicador. Usá el puntaje, los indicadores, el comportamiento de red y la información TLS como evidencia para revisar, y confirmá los hallazgos importantes con análisis adicional cuando sea necesario."),
        HelpSection("26. \"Inteligencia de amenazas (0 dominios)\" en Seguridad", "Esta fila es independiente de la blocklist de anuncios/rastreadores, que viene incluida en la app y ya está activa. Cuenta una lista dedicada de dominios de amenazas/malware (hoy HaGeZi Threat Intelligence mini) que solo se completa cuando corrés una actualización desde la pantalla de actualización de listas con esa fuente habilitada. Hasta que lo hagas al menos una vez, esta fila normalmente queda en 0 dominios — eso es lo esperable en una instalación nueva, no un error."),
        HelpSection("27. \"Aprendizaje local de comportamiento (0 apps)\" en Seguridad", "Cuenta cuántas apps ya tienen un perfil de tráfico aprendido en el propio teléfono. Depende del registro de tráfico del Analizador, que viene DESACTIVADO por defecto. Activá el registro en la pestaña Analizador, usá el teléfono con normalidad un rato para que se registre tráfico real, y después volvé a abrir el Centro de seguridad — esa pantalla recalcula este número con el tráfico registrado cada vez que la abrís. Con el registro apagado, esto queda en 0 aunque el firewall esté filtrando tráfico con normalidad."),
    )

    Column(
        Modifier.fillMaxSize().verticalScroll(rememberScrollState()).padding(horizontal = 12.dp, vertical = 10.dp),
        verticalArrangement = Arrangement.spacedBy(8.dp)
    ) {
        Text("HYDRA HELP", style = MaterialTheme.typography.headlineSmall, fontWeight = FontWeight.Bold)
        Text(title, style = MaterialTheme.typography.titleMedium)
        HydraCard(Modifier.fillMaxWidth()) {
            Column(Modifier.padding(12.dp), verticalArrangement = Arrangement.spacedBy(6.dp)) {
                Text(intro, style = MaterialTheme.typography.bodyMedium)
                Text(if (en) "Quick start: turn VPN ON → configure the default policy → review app rules → inspect Connections/Analyzer when troubleshooting." else "Inicio rápido: activá la VPN → configurá la política predeterminada → revisá las reglas de las apps → consultá Conexiones/Analizador cuando quieras investigar un bloqueo.", style = MaterialTheme.typography.bodySmall)
            }
        }
        sections.mapIndexed { i, sec ->
            sec.copy(title = "${i + 1}. " + sec.title.replace(Regex("^\\d+\\.\\s*"), ""))
        }.forEach { section ->
            HydraCard(Modifier.fillMaxWidth()) {
                Column(Modifier.padding(12.dp), verticalArrangement = Arrangement.spacedBy(5.dp)) {
                    Text(section.title, style = MaterialTheme.typography.titleSmall, fontWeight = FontWeight.Bold)
                    Text(section.body, style = MaterialTheme.typography.bodySmall)
                }
            }
        }
        Spacer(Modifier.height(8.dp))
    }
}

